def antiemetics(level,day):
    meds=[med('Ondansetron','16 mg orally once' if level=='Moderate' else '8 mg orally once',f'Before chemotherapy on Day {day}','Review QT risk, constipation, hepatic function and any alternative local regimen.')]
    if level=='Moderate':meds.append(med('Dexamethasone','8 mg orally once daily',f'Days {day}, {day+1} and {day+2}','Reconcile total steroid exposure; individual adjustments require prescribing review.'))
    meds.append(med('Metoclopramide','10 mg orally up to three times daily as needed','Rescue duration to be specified','Review renal function, contraindications and interactions before prescribing.'))
    return meds

